INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2749770b-d20d-4b3b-a16a-97a783cd5e06', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$51. óra: A kör$q$, $q$A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "f66a7331-4cd8-4960-8c56-7783cd0832b7", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "d5c4e0e6-4054-48f4-bf76-6de8d0be4346", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "5208c7ff-2321-4a3a-862c-cc3858f6a6fb", "text": "d = r / 2", "isCorrect": false}, {"id": "3872971a-486d-46c0-a159-7d6914841644", "text": "d = r + 5", "isCorrect": false}, {"id": "e988ee25-df22-47f0-b258-de4b8856fe24", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "05499171-e1b4-4454-a02d-972a49143aab", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "6c376f6c-5b28-473a-bee3-a9e305673b46", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "0c9be523-117e-4a82-b987-91e2f34b0c45", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "1c2be645-3d0a-4305-8997-e6750bd2d5ee", "text": "Igaz", "isCorrect": true}, {"id": "9c0058f4-0698-439b-bc68-1666a328c5e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2cda16a7-f138-4601-914f-d28f158baa8d", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "96bc1f91-e47e-400e-ab97-ececf41680e8", "text": "Az átmérő", "isCorrect": true}, {"id": "5c8b1f04-6534-48d7-9ce5-29bf2a1ec5a6", "text": "A sugár", "isCorrect": false}, {"id": "a9822d19-7f9d-4d57-aac8-aad49ec11dee", "text": "A körív", "isCorrect": false}, {"id": "5594a67b-6009-485e-83e8-404d3034eceb", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "8277a4d8-73bb-4c9b-a9ae-7e3128926f53", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "945a9be7-04a2-4835-b2b0-5f7430d78c87", "text": "Igaz", "isCorrect": true}, {"id": "5d0bc87e-0deb-46f0-9d9a-8e150a4e64ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9116e20-2036-4149-b8a1-88c2509e7332", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "b65426e6-52ae-4351-acf3-14b76040bd10", "text": "Igaz", "isCorrect": true}, {"id": "f55aca2c-7664-4fa5-a95b-78a2e462ae31", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1986a96d-cfa4-43c3-bb03-6655b007dfec', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$52. óra: A szakasz felezőmerőlegese$q$, $q$A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "1ba12d53-c217-48a0-86d6-aab395b280ec", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "c92f052b-4df4-4c56-a4fd-80f915dc2da6", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "8e04470d-112c-47de-9e41-29899debdd09", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "ea194980-cf29-4b8f-ab17-2e99d6733ad0", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "7ac9339f-6049-45c9-9b31-0770b8eba272", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "10521e5d-5064-4f44-a6e5-0dc6bffc6d58", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "853dd72f-ebc2-4b7c-8252-f74513c04634", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "1927a3b7-4072-4bb4-ab16-998fc45ab9b5", "text": "Igaz", "isCorrect": true}, {"id": "fa22e6c6-1928-459e-8cf4-13aaacee2679", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "55f24c57-7f44-4026-b863-b369132b5b80", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "1f7c0f31-31d4-41a7-a4d0-e8970a51a39f", "text": "Igaz", "isCorrect": true}, {"id": "fafa6d62-a6e2-49cf-9075-d5228369231a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df1f54af-8e54-4e86-9f72-932820510ce5", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "c2d6d432-e671-4272-aa25-47c44b3c3166", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "a48ed7f6-23c0-4781-b2cf-a9a310afbfbe", "text": "Igaz", "isCorrect": true}, {"id": "7f88fe51-606b-422d-9bae-926c3069059e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a23e2ac6-90dd-47d2-8ef4-b6ace3122ddc", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "e53d627f-de75-475c-baaa-79cbac70ef4e", "text": "Igaz", "isCorrect": true}, {"id": "f2ad3ed4-fccc-4762-9a78-6d5af3b93b73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4b76f88c-9cda-4e55-bcef-b49de2adba1a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$53. óra: Szerkesztések$q$, $q$Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "47331bda-5dd4-48ec-9bcf-03070f1ce233", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "dbbff79c-e4e5-483c-a4c3-00c60fccf0e5", "text": "Körzőt", "isCorrect": true}, {"id": "90a040ec-a26d-4b86-bf49-2f52e2ca5dd9", "text": "Szögmérőt", "isCorrect": false}, {"id": "9c5f8bbb-d6dc-4644-b3bf-cf83f1866512", "text": "Radírt", "isCorrect": false}, {"id": "c8549e5b-74c5-4498-bb00-0aee8dd9a4d5", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "44c47154-57cd-4504-810b-85cae2cba081", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "650b7624-565d-4a68-9706-f9c57cfb64f1", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "b7ef393f-bb0d-4afa-bcae-fa8f158c231c", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "06e093ec-f40b-4c43-90c1-d3f85154f66a", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "e0794837-5318-4373-9ee1-8698d6415c86", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "90c94148-808b-4439-b6b3-f1da0503b32d", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "d42b8655-ab6b-43af-a3ed-94abcadde451", "text": "Igaz", "isCorrect": true}, {"id": "a16085f6-104a-4000-9742-24335a67b8d0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7b7cfb36-0f56-45fa-b72e-9602d6e6257d", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "149f2174-d154-4575-a378-3481a81a0994", "text": "Igaz", "isCorrect": true}, {"id": "59a99097-4d83-4e89-a801-899ce61eacc2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "84750b21-6798-4b22-bef9-1c34f3bb7430", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "ca53ca46-ffd5-4259-85a0-491c5f872bd3", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "4945a59c-85bd-466d-a86d-27b441b7046b", "text": "Igaz", "isCorrect": true}, {"id": "ac822b17-9afd-49a3-acc9-e470beee3561", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c610025-4e0e-4f4a-83ac-12d274ba15db", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "e89eae70-272f-4a70-8d83-795409aae10f", "text": "Igaz", "isCorrect": true}, {"id": "159a935f-b7d0-4914-9153-a6677c270eae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a99618eb-e70f-4f69-92d0-642a03395ce9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$54. óra: Szerkesztések II.$q$, $q$Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "ca60e0c1-831e-4dc7-995f-13a5b0f4f776", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "3f151dec-2919-41a7-bece-95a3711b5d60", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "c5c14506-3830-409b-abe1-293e15d71d6d", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "5c1406eb-6cdb-49e2-9c87-da8ddcbbb828", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "a768f275-fa02-4316-a0ee-a0099211cb40", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "fb7fe331-4856-4962-ad0c-11131f6ad57b", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "2376843d-4d26-4dad-b38e-9d67a196cc02", "text": "Igaz", "isCorrect": false}, {"id": "7c167042-04aa-4f33-991e-eec4eebc48c7", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "7991d390-25da-4d72-84c7-5906f915073f", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "6439f7d0-d241-40fe-95d3-74bdbfdb0c83", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "bdb69e7c-4835-4471-89cf-77bb1fa598a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7fba36de-5007-4727-90aa-e3a8e3d897b1", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "da5db45b-8bbf-4c7a-b9ae-7da51ab397a3", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "ec3e44f5-3184-4ba4-8c5c-9f6e27c65f07", "text": "Igaz", "isCorrect": true}, {"id": "668284f9-025d-4930-965a-ed1f523fa9fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15fe4969-2bf5-4fe0-8a28-5fe479987d32", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "950823b9-d281-4e23-80a7-db6cc0362bcc", "text": "Igaz", "isCorrect": false}, {"id": "dc90ca06-ab5f-48bd-9b4c-623b9bae7a0b", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "308de898-683a-4a4a-9901-6dc27dd26983", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "732c54c2-8550-4579-b10a-8f03e306a6a6", "text": "Igaz", "isCorrect": true}, {"id": "e429906e-8782-475f-b155-0277d79ac962", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bcdb3537-5e79-4e0f-a3b7-502daf38ff7e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$55. óra: Számonkérés$q$, $q$Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "be6a79ce-0c74-4f11-a9a9-14a8062809bd", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "2c66b13a-172a-4771-af83-056d6e007ba3", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "082a6dac-2659-4115-bb5b-25765f11dc15", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "954dcee6-1082-4ea2-b814-fb55efb353f9", "text": "Igaz", "isCorrect": false}, {"id": "d5600022-1c86-4177-b99f-98baff01bfbd", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "17147044-169a-4d7c-a7f6-c91060576fe4", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "79f2d596-2d18-4d02-9244-24097165cd2e", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "58424c7f-bf95-4a0c-aa6e-43adbad9b763", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "e6c334d7-07e6-4d26-8b52-2233c21c58fe", "text": "Igaz", "isCorrect": true}, {"id": "cc71208f-2010-43dd-acf8-837f22fdb827", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "125dee03-641f-4e11-80cc-cd114c0e658d", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "ce63646a-3f66-423c-a5bd-2b700b6d98e2", "text": "Tompaszög", "isCorrect": true}, {"id": "595edaae-ff29-463c-b7b8-a6046d43828b", "text": "Hegyesszög", "isCorrect": false}, {"id": "eaab7741-b8b1-44ef-950c-8dd8b1171350", "text": "Derékszög", "isCorrect": false}, {"id": "495adbb9-a42b-41a3-b0d3-5bce45cc2bed", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "c73021a1-78f4-4508-831e-c779532a4ba4", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8ba5dd95-256e-4699-9a18-8f00803c719d", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "8fab01f0-147c-4d37-a970-0a500f9bbaee", "text": "Igaz", "isCorrect": true}, {"id": "935af373-80ec-4316-9719-b1afd0ef65ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f1515d0-cd2a-4b01-b099-ec19b4f9c7f8", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2fa71c83-a75f-4de5-b3d4-561336677f78', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$56. óra: Matematikai játékok$q$, $q$Geometriai kirakók (Tangram), alakzatok építése, stratégiák.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "129b2d4a-4523-4187-aa5a-e4bfdf0c7645", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "483d7421-acc6-4b69-b541-af626238fd28", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "9ab25ee3-c386-4c62-85ea-8e993bbce670", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "d5f33e61-5527-40a9-b288-9112c7dccdee", "text": "7 négyzet", "isCorrect": false}, {"id": "883e1ee4-e023-462b-bf88-6ba079955821", "text": "7 kör", "isCorrect": false}, {"id": "ec655333-7184-448a-9b84-f346dda10341", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "dcc1e0e1-6a02-4cda-a06e-10e9a326eba6", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "a28f31ee-528d-4ff2-acaf-30eab369620a", "text": "Igaz", "isCorrect": true}, {"id": "f7c63c71-2b32-4ed6-8def-68d3fa016eb3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "05bab74c-86bb-4491-afae-fa011da3941b", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "bfdb038e-b3bd-4980-8b67-ca30772774a6", "text": "Igaz", "isCorrect": true}, {"id": "af16dbf5-eb07-478d-a7f3-e139e1b12da9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53ea4cf8-cc87-4df6-8e5f-24a45530e320", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "3c316dd5-ff45-4d79-a30c-9ad8595468a7", "text": "Igaz", "isCorrect": true}, {"id": "4c04b70e-b0b4-4d24-8985-7b9d35196d48", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a5cb13aa-42d2-4f07-8abf-f77d8807cd14", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "f0dc348b-0967-4633-9c99-4cad4ba1ac88", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "4b3f7922-6d0e-4d98-af61-5d423289702a", "text": "Igaz", "isCorrect": true}, {"id": "1ed2e8c5-1d92-4657-b439-aec4bf90b444", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3330d9f3-7b29-413c-8662-4c0b0511c16a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$57. óra: Tengelyes tükrözés$q$, $q$Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A').$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "e4579a27-227c-4032-b046-519474a8e329", "text": "Mi a tengelyes tükrözés lényege egy 't' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "ca15cb6e-3069-4dc3-8cc2-ab8945f3ba38", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "bc215a43-15e0-4b1a-8b91-85fca3b1b3f2", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "5e756d13-48c7-479b-ae51-ffd7ef5a7d5a", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "af73e794-8e2e-4ebc-a0d1-3278fe06eaa0", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "48e986e6-731c-447a-b717-70f678f9be1d", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "7d6c6962-88d5-45a1-8450-b8816eb32801", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "d9d0ca95-4bf0-4dbf-b1c8-73b8e4a3c296", "text": "Az origóban", "isCorrect": false}, {"id": "1e0ea4ce-29e1-4a13-aca9-c7db0a0fdc86", "text": "Végtelenben", "isCorrect": false}, {"id": "632a8169-c132-402e-ae46-a6af504c9ba3", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "d8b3ebbb-fc70-4325-a450-e1aeba29f5e3", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "f271c3a2-e615-44bf-84f1-07a900f8843a", "text": "Milyen messze van a P pont a P' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "85bbf909-333b-48be-a82e-0db560084da8", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "bb41a934-b56a-43bf-96ca-6f65daf469db", "text": "Igaz", "isCorrect": true}, {"id": "0e1a1b1d-409c-4393-9ec5-8d2cdd6578be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a5c051d4-08f5-447f-ab43-0d55d56963cd", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "8e1be79e-6d3b-404b-8ae0-f13ec5a81874", "text": "Igaz", "isCorrect": true}, {"id": "9f134d45-eeed-4038-a8bd-dcf90faad292", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2bfe6e1-f367-45af-b6a6-88ab9244f2e0", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "054bfe64-e4f7-4f7d-a237-9f00c0c22658", "text": "Igaz", "isCorrect": true}, {"id": "b24b8fcf-241b-4858-8af9-f40750725157", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('308f0cae-83f8-4286-932d-82db5fc2609d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$58. óra: A tengelyes tükrözés tulajdonságai$q$, $q$Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "a0ca8049-911f-4619-a3b3-266bfc2d02dd", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "41cdcb1a-3617-436b-bd20-c69f7e0478bd", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "b653902e-7520-4211-ad4a-38d32b0f7bfb", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "10b4c602-2046-42e0-aad9-20e70597b123", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "c9367f6b-3b69-4ab4-b573-a745146fe546", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "852e555f-9f56-4839-a21f-61085242b90b", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "b9532be2-4e38-4369-be9a-74f3b39b2e15", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "52c7e7fc-ea62-4528-82ff-3d855026d3a4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5494aaf8-d4ff-4e2d-a289-5f4911cef10a", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "6a4e6e8f-4b76-4776-8112-82eda25148bc", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "b3242eba-21cc-4fb4-ab28-aa64734d2977", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fda050eb-60b2-4c4b-b1cc-644571882f21", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "dcf5e09b-cb7a-4d88-b78b-8f5bf12c0414", "text": "Igaz", "isCorrect": true}, {"id": "f421e28f-d6d9-42d1-bb51-a25695521c69", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "869f56a5-501c-4296-8506-3fdf2de74a32", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "2d946f93-7c39-40e6-9b24-fc142fcee5b8", "text": "Igaz", "isCorrect": true}, {"id": "2a206a3d-0056-4698-b333-d7b5daceb826", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aec4efa8-1e1f-4284-8356-21133aa4bb70", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "18bc1874-3290-42a8-a532-509ad1a5fedb", "text": "Igaz", "isCorrect": true}, {"id": "ee14a25b-1a39-4b5a-9e44-04df40923419", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c8128c6f-3d72-423d-ba68-aac481619467", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "74648c2d-ecdb-4f74-a099-43f0eb90f8b5", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "b745ca46-3daf-4140-81e2-124c920c8b3e", "text": "Csak 1", "isCorrect": false}, {"id": "0840887e-9511-4d69-a32f-347175fa31cd", "text": "Nincs egy sem", "isCorrect": false}, {"id": "1fd96915-d553-4a96-8533-fbc85bd0a1ab", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('981449b4-6318-4874-ab6d-c306a566f670', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$59. óra: Gyakorlóóra$q$, $q$Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "8e7f7bf6-803c-462b-9a3b-a7a59cbb09dd", "text": "Hogyan szerkesztjük meg egy P pont 't' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "0c0a0350-b256-4c92-8e90-c21d5075d736", "text": "Merőlegest állítunk P-ből 't'-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "97dac1a2-db87-42fe-9a72-9bdfe6a95de1", "text": "Párhuzamost húzunk 't'-vel", "isCorrect": false}, {"id": "d15ffc78-d5b3-444a-822f-dac18c4bec8d", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "b8876102-5087-493e-a464-383ed38c3e39", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "f8396bf2-fa14-4819-9d99-fce46b5d2bcf", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "e2141194-281e-4a82-a507-d6ac91648e5d", "text": "Igaz", "isCorrect": true}, {"id": "4081ad5b-1860-4424-8f35-bbb8797a1ba9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a7d0dd5f-d578-40e6-aae2-216f5b6ea21e", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "d8941509-173a-4ee9-a349-cd6fa3ca311c", "text": "Önmagában (P = P')", "isCorrect": true}, {"id": "a7e2ccce-402e-4cd5-96f5-927a0b397dcf", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "c418bc03-aa5a-48f4-8974-b88aef51443d", "text": "A sík szélén", "isCorrect": false}, {"id": "4d52ac7f-acfe-407d-8909-8beb3d9b8ec3", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "d4825454-7cc2-499c-83ac-75708b243d14", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "3bfb7fa6-f3e2-4052-9600-98e5c4ea68b8", "text": "Igaz", "isCorrect": true}, {"id": "415f0291-f937-46fc-8614-a6d6f0d8d39d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5fac61a-e9d0-483d-98a2-40c5d9ca69ff", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "fd46ffff-ab47-4fac-87c9-4bf2d24b0457", "text": "A", "isCorrect": true}, {"id": "b64ca401-b9fd-4c54-b542-325b6434de37", "text": "F", "isCorrect": false}, {"id": "49c69ba7-5a3d-45a2-8084-c9c7b6117b6e", "text": "L", "isCorrect": false}, {"id": "10e4be3e-06a0-4b08-90d7-0880adfe40b8", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "2349d08d-844f-420e-8f97-6dbde50703d2", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "2b5a9aaa-2c20-4e17-9650-108cafdcbcd9", "text": "E", "isCorrect": true}, {"id": "dd3fca47-9ee6-4583-8b2e-37a23b54b783", "text": "F", "isCorrect": false}, {"id": "dbcae4ce-61d4-4e58-a2f0-cd90a07500bc", "text": "G", "isCorrect": false}, {"id": "2e7b7bcb-e51c-4224-8e8f-d7d4bf207223", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "64341539-ed15-4750-985b-ef088f4725fd", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "49278e6e-dffb-40e5-9e89-27f4240d67c3", "text": "Igaz", "isCorrect": true}, {"id": "e953b002-0fd2-48ad-900d-8e9f315aacf6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('13e19fec-26bd-4b14-b704-1c563f200bc9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$60. óra: Tengelyes szimmetria$q$, $q$Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "0efbe3b0-2e3d-4057-8f89-240922dd34da", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "8c1525a9-eab0-4b7e-ba5d-3902ce80cd56", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "1ed39ef8-8dfc-4750-ab3a-c43402cc2d4a", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "63bcfea2-87e9-4547-a82f-9d47993a4e7e", "text": "Ha kerek", "isCorrect": false}, {"id": "bee44bf9-e8fb-4612-ac7f-207c07a84c8d", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "4a26f797-5fde-4e0d-9c1a-e42cf272b669", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "5808b467-2ec1-48e5-bf8e-5d4560ac3eb8", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "5dcc4f72-793f-43a7-ac28-17339a159086", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "4288ca43-ebc0-4a6d-98e0-a73297f0ce35", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "a871a116-996c-4800-8322-1eaf02677983", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "585538e2-72f5-460b-8c17-250cd1c1521f", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "891e6985-b24d-4fa5-86ac-3b9e30ec4ac3", "text": "Igaz", "isCorrect": true}, {"id": "7358f14f-db65-42e8-80be-414eb33bf855", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "86dc87ab-eb5e-44ab-a743-9170cf96e06f", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "5f3c6a68-b139-4f1b-8bad-ba9f19db9ecd", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "02201038-3edb-4794-9284-49e694bfb2c0", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "669d35db-75c5-435f-9a8d-ab56dd6f7bda", "text": "1", "isCorrect": false}, {"id": "e7266a9c-2013-4f4f-904c-8d51c98cc8dd", "text": "2", "isCorrect": false}, {"id": "d382d04d-f0f2-45cb-a969-66c880fbf7b3", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "5c515065-e037-4bdd-9f68-1f88fc3efbce", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "a480271b-62d9-425b-a194-cb3bf5c41fbb", "text": "Igaz", "isCorrect": true}, {"id": "6ccad90c-689c-4d7a-a86d-ad501f181183", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9f2536af-4373-47fa-a3e3-e826a98ca0df", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;